<?php

use App\Enums\ElectionBallotRefusal;
use App\Models\EinundzwanzigPleb;
use App\Models\ElectionRound;
use App\Services\Election\CloseRound;
use App\Services\Election\OpenRound;
use Illuminate\Support\Carbon;

require_once __DIR__.'/helpers.php';

/*
 * I4: when a round takes a ballot, decided at the cast against the clock of
 * that transaction and on the round row as it is now.
 *
 * The window and the clock positions are generated by Carbon; the clock is
 * travelled, so a cast that reads the time anywhere but from `now()` sees
 * the real date and fails every case.
 */

/**
 * A window round 2027-03-01 09:00:00 → 2027-03-03 18:00:00 (UTC), opened
 * the day before, and a voter on its roll.
 *
 * @return array{0: ElectionRound, 1: EinundzwanzigPleb}
 */
function windowRoundAndVoter(): array
{
    test()->travelTo(Carbon::parse('2027-02-28 12:00:00'));

    $voter = electionVoter(2027);
    $round = ElectionRound::factory()->withCandidates()
        ->window(Carbon::parse('2027-03-01 09:00:00'), Carbon::parse('2027-03-03 18:00:00'))
        ->create();

    return [app(OpenRound::class)->handle($round), $voter];
}

/*
 * Mutations that must turn this red:
 *  M4a `$now->lt($this->closes_at)` → `lte` in `ElectionRound::stateAt()` — exactly closes_at;
 *  M4b drop the `opens_at` check in `stateAt()` — one second before opens_at;
 *  M4c read the clock in `CastBallot` with `time()` instead of `now()` — every case.
 */
it('takes a ballot from the opening instant up to, not including, the closing instant', function (Closure $at, bool $accepted) {
    [$round, $voter] = windowRoundAndVoter();

    $this->travelTo($at($round));

    $refusal = electionRefusal(fn () => castElectionBallot($round, $voter));

    expect($refusal)->toBe($accepted ? null : ElectionBallotRefusal::RoundNotOpen)
        ->and(electionVoteCount($round))->toBe($accepted ? 1 : 0);
})->with([
    '1 s before opens_at' => [fn (ElectionRound $round) => $round->opens_at->copy()->subSecond(), false],
    'exactly opens_at' => [fn (ElectionRound $round) => $round->opens_at->copy(), true],
    '1 s before closes_at' => [fn (ElectionRound $round) => $round->closes_at->copy()->subSecond(), true],
    'closes_at − 1 µs' => [fn (ElectionRound $round) => $round->closes_at->copy()->subMicrosecond(), true],
    'exactly closes_at' => [fn (ElectionRound $round) => $round->closes_at->copy(), false],
]);

/*
 * Mutation that must turn this red: M4d — `CastBallot` takes a live round
 * whatever its state (`stateAt()` is asked only of window rounds).
 */
it('refuses a ballot in a live round until the chair opens it, and after the close', function () {
    $voter = electionVoter();
    $round = draftElectionRound();

    $this->travelTo(now()->addDays(30));

    expect(electionRefusal(fn () => castElectionBallot($round, $voter)))->toBe(ElectionBallotRefusal::RoundNotOpen)
        ->and(electionVoteCount($round))->toBe(0);

    $round = app(OpenRound::class)->handle($round);
    $round = app(CloseRound::class)->handle($round);

    expect(electionRefusal(fn () => castElectionBallot($round, $voter)))->toBe(ElectionBallotRefusal::RoundNotOpen)
        ->and(electionVoteCount($round))->toBe(0);
});

/*
 * Interleave: the voter's page loaded the round while it was open, the chair
 * closes it, then the ballot arrives with the instance from before.
 *
 * Mutation that must turn this red: M4e — check the state only on the
 * caller's instance, not on the row re-read and locked in the transaction.
 * (The race between two connections is the engine suite's,
 * `tests/Engine/ConcurrentBallotCastingTest.php`.)
 */
it('refuses a ballot that arrives after the chair closed the round, on a stale instance', function () {
    $voter = electionVoter();
    $round = openElectionRound();
    $stale = ElectionRound::query()->findOrFail($round->id);

    app(CloseRound::class)->handle($round);

    expect(electionRefusal(fn () => castElectionBallot($stale, $voter)))->toBe(ElectionBallotRefusal::RoundNotOpen)
        ->and(electionVoteCount($round))->toBe(0);
});
